JS=r'''
var ASK='dq',DEP=0,cv=$('#c1');
function hybrid(mode,qk,dep){var T=660,ok=QIDX.map(function(i){var j=latestOf(i);if(factAge(j)<=600)return useProb(1-factAge(j)/T,dep);var r=scoreRetrieve(mode,qk,true);return r.ok[i]?useProb(620/T,dep):0;});return {ex:ok,n:ok.reduce(function(a,b){return a+b;},0),cost:T};}
function table(){var d=DEP/10;return [['최근 것만 (창 1,000)',scoreMiddle(1000,d).n,1000],['전부 넣기 (창 3,600)',scoreMiddle(3600,d).n,3600],['요약하며 가기',scoreCompact(1000,0.8).n,720],['낱말로 꺼내 읽기',scoreRetrieve('word',ASK,true).n,60],['뜻으로 꺼내 읽기',scoreRetrieve('tag',ASK,true).n,60]];}
function upd1(){var t=table(),best=0;t.forEach(function(z,i){if(z[1]>t[best][1]+1e-9||(Math.abs(z[1]-t[best][1])<1e-9&&z[2]<t[best][2]))best=i;});
  $('#ins1').innerHTML=tpl('<p class="g">이 조건에서 가장 많이 맞히면서 가장 적게 읽는 것은 “{0}”예요. 맞힐 질문 {1}개, 읽는 글 {2}조각.</p>',t[best][0],f2(t[best][1],1),t[best][2].toLocaleString())+(DEP?'<p>가운데가 덜 쓰인다고 보면 전부 넣기의 성적이 내려가요. 꺼내 읽기의 숫자는 “맞는 쪽지를 찾았는가”까지만 센 것이라 이 가정의 영향을 받지 않게 뒀어요.</p>':'')+(ASK==='iq'?'<p>다른 말로 물으니 낱말로 꺼내 읽기가 한 개도 못 찾아요.</p>':'');drawAll();}
toggleGroup('#g1A button',function(v){ASK=v;upd1();});toggleGroup('#g1D button',function(v){DEP=+v;upd1();});
addMod(cv,function(){var t=table(),H=30+t.length*56,W=fit(cv,H),ctx=cv.getContext('2d');ctx.clearRect(0,0,W,H);var x0=Math.min(200,W*0.36),bw=W-x0-110;
  t.forEach(function(z,i){var y=30+i*56;txt(ctx,z[0],8,y+16,{size:12,color:COL.text,w:'700'});
    rr(ctx,x0,y,Math.max(2,z[1]/10*bw),18,4,'rgba(94,227,156,.75)');txt(ctx,f2(z[1],1)+' / 10',x0+Math.max(2,z[1]/10*bw)+8,y+9,{size:12,color:COL.gfp,w:'700'});
    rr(ctx,x0,y+22,Math.max(2,z[2]/3600*bw),12,3,'rgba(157,155,184,.5)');txt(ctx,z[2].toLocaleString()+'조각',x0+Math.max(2,z[2]/3600*bw)+8,y+28,{size:11,color:COL.muted});});
  txt(ctx,'초록 = 맞힐 질문 (길수록 좋음) · 회색 = 요청마다 읽는 조각 (짧을수록 좋음)',8,14,{size:10,color:COL.muted});stamp(ctx,W,'설명용 모형');});
/* 칸 ② */
var MD='tag',A2='iq',cv2=$('#c2'),cv2b=$('#c2b');
function upd2(){var r=hybrid(MD,A2,0);
  kpis($('#k2'),[['600조각','최근 5일 원문','a'],['40조각','찾아온 쪽지 한 장','g'],['660조각','요청 하나에 읽는 글','m'],[f2(r.n,0)+' / 10','맞힌 질문',r.n>=9.5?'g':'r']]);
  $('#ins2').innerHTML=r.n>=9.5?'<p class="g">최근 5일 안에 있는 것은 원문에서, 그 앞의 것은 찾아온 쪽지에서 답이 나왔어요. 660조각으로 열 개를 다 맞혔어요.</p>':tpl('<p class="r">찾기가 쪽지를 못 가져오니 꺼내 읽기 층이 비었어요. 최근 5일 원문에 있는 {0}개만 맞혔어요.</p>',f2(r.n,0));drawAll();}
toggleGroup('#g2M button',function(v){MD=v;upd2();});toggleGroup('#g2A button',function(v){A2=v;upd2();});
addMod(cv2,function(){drawDays(cv2,{win:600,H:110,title:'30일 대화 (노랑 = 원문으로 넣은 최근 5일 · 그 앞의 ★는 서랍 속 쪽지)'});});
addMod(cv2b,function(){drawBoard(cv2b,hybrid(MD,A2,0).ex,'섞어 썼을 때');});
PAGE._T={h5:hybrid('tag','iq',0.5).n,h0:hybrid('tag','iq',0).n,hw:hybrid('word','iq',0).n,full5:scoreMiddle(3600,0.5).n};
/* 대결 */
Duel({el:'#duel',higherIsBetter:true,drawMargin:0.05,fmt:function(v){return f2(v,1)+'개';},run:function(){return {fly:hybrid('tag','iq',0.5).n,robo:scoreMiddle(3600,0.5).n,metric:'맞힐 질문 수'};},
  say:function(f,b){return tpl('맞힐 질문은 초파리 쪽 섞어 쓰기가 {0}개, 주판봇 쪽 전부 넣기가 {1}개로 기대돼요. 읽는 글은 660조각 대 3,600조각이에요.',f2(f,1),f2(b,1));},
  lessons:{F:'작은 것을 맞게 섞은 쪽이 통째로 넣은 쪽을 앞섰다. 다만 가정 두 개가 받쳐 줄 때의 이야기다',D:'이 가정에서는 둘이 비슷했다',R:'통째로 넣은 쪽이 앞섰다'},
  after:function(){$('#duelNote').innerHTML=tpl('<p>가운데 놓침이 없다고 보면(깊이 0) 섞어 쓰기 {0}개, 전부 넣기 10.0개로 비겨요. 뜻으로 찾기가 실패한다고 보면 섞어 쓰기는 {1}개로 내려가요. 가정에 따라 승자가 달라지는 판이에요.</p>',f2(hybrid('tag','iq',0).n,1),f2(hybrid('word','iq',0.5).n,1));}});
upd1();upd2();
'''
